const $=s=>document.querySelector(s), app=$('#app'), catalog=window.TOY_CATALOG;
const rooms=[{id:'andy',name:'Andy',tag:'Um céu de aventuras'},{id:'buzz',name:'Buzz',tag:'Ao infinito e além!'},{id:'bonnie',name:'Bonnie',tag:'Imaginação sem fim'},{id:'blaze',name:'Blaze',tag:'Aventura no rancho'},{id:'molly',name:'Molly',tag:'A irmã do Andy'}];
let mode='search',room='andy',sound=false,items=[],targets=[],selected=null,placing=null,won=false,toastTimer;
let saved={};try{saved=JSON.parse(localStorage.getItem('toy-adventure-v1'))||{}}catch{};
function save(){try{localStorage.setItem('toy-adventure-v1',JSON.stringify(saved));return true}catch{notify('Não foi possível salvar neste navegador.');return false}}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notify(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',2600)}
function chime(){if(!sound)return;try{const c=new(window.AudioContext||window.webkitAudioContext)(),o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);o.frequency.setValueAtTime(660,c.currentTime);o.frequency.setValueAtTime(880,c.currentTime+.1);g.gain.setValueAtTime(.08,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.3);o.start();o.stop(c.currentTime+.32);o.onended=()=>c.close()}catch{}}
$('#sound').onclick=()=>{sound=!sound;$('#sound').setAttribute('aria-pressed',sound);$('#sound').setAttribute('aria-label',sound?'Desativar sons':'Ativar sons');notify(sound?'Sons ativados':'Sons desativados');chime()};
$('#count').textContent=catalog.length;document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>b.dataset.nav==='home'?home():showCatalog());$('.brand').onclick=e=>{e.preventDefault();home()};
function roomCards(){return rooms.map((r,i)=>`<button class="room" data-room="${r.id}"><img src="assets/${r.id}.png" alt="Quarto de ${r.name}, vazio, com mobília" loading="lazy"><div class="room-info"><div><b>${r.name}</b><small>${r.tag}</small></div><span class="room-number">0${i+1}</span></div></button>`).join('')}
function home(){}
function choose(m){mode=m;app.innerHTML=`<section class="content"><div class="toolbar"><button class="back" id="back">← Início</button><span class="mini-label">${m==='search'?'PROCURAR BRINQUEDOS':'MONTAR E VESTIR'}</span></div><div class="section-head"><div><h1>Onde vamos brincar?</h1><p>Escolha um quarto para começar.</p></div></div><div class="rooms">${roomCards()}</div><div class="status">Os quartos estão prontos para receber os brinquedos. Por enquanto, experimente com fichas de nomes.</div></section>`;$('#back').onclick=home;document.querySelectorAll('[data-room]').forEach(b=>{b.classList.toggle('active',b.dataset.room===room);b.onclick=()=>{room=b.dataset.room;start()}});window.scrollTo(0,0)}
function start(){mode='search';selected=null;placing=null;won=false;const pool=catalog.filter(t=>t.kind==='individual').slice(0,35).sort(()=>Math.random()-.5).slice(0,12);items=pool.map((t,i)=>({uid:i,id:t.id,x:10+(i%4)*26+Math.random()*5,y:48+Math.floor(i/4)*19,found:false}));targets=items.slice().sort(()=>Math.random()-.5).slice(0,5).map(t=>t.uid);renderGame()}
function renderGame(){const r=rooms.find(r=>r.id===room);app.innerHTML=`<section class="workspace"><div class="toolbar"><button class="back" id="back">← Quartos</button><h1>Procurar / ${r.name}</h1><div class="controls"><button id="hint">☀ Uma pista</button><button id="restart">↻ Misturar</button></div></div><div class="game-layout"><div><div class="board" id="board" aria-label="Quarto interativo"><img src="assets/${room}.png" alt="Quarto de ${r.name}"><div id="pieces"></div></div><div class="status">Encontre os 5 brinquedos da lista. Sem relógio e sem perder pontos!</div></div><aside class="sidebar" id="sidebar"></aside></div></section>`;$('#back').onclick=()=>choose('search');$('#hint').onclick=hint;$('#restart').onclick=start;draw()}
function draw(){const pieces=$('#pieces');pieces.innerHTML=items.map(i=>{const t=catalog.find(t=>t.id===i.id);return `<button class="toy ${t.asset?'image-only':''} ${i.found?'found':''}" data-uid="${i.uid}" style="left:${i.x}%;top:${i.y}%" aria-label="${esc(t.name)}" ${i.found?'disabled':''}>${t.asset?`<img src="${esc(t.asset)}" alt="">`:esc(t.name)}</button>`}).join('');pieces.querySelectorAll('.toy').forEach(b=>b.onclick=()=>find(items.find(i=>i.uid===Number(b.dataset.uid))));drawSide()}
function find(i){if(!targets.includes(i.uid)){notify('Esse amigo não está na lista. Continue procurando!');return}i.found=true;chime();draw();if(targets.every(id=>items.find(i=>i.uid===id).found)){won=true;saved.completed={...saved.completed,[room]:true};save();$('#board').insertAdjacentHTML('beforeend','<div class="win" role="status"><h2>★ Você encontrou todos! ★</h2><p>Que dupla de olhos atentos!</p><button class="action" id="again">Brincar de novo</button></div>');$('#again').onclick=start}}
function hint(){const i=items.find(i=>targets.includes(i.uid)&&!i.found);if(!i)return;const b=document.querySelector(`[data-uid="${i.uid}"]`);b.classList.remove('hint');void b.offsetWidth;b.classList.add('hint');notify('Olhe onde está brilhando!')}
function drawSide(){$('#sidebar').innerHTML=`<h2>Vamos encontrar</h2><p>${targets.filter(id=>items.find(i=>i.uid===id).found).length} de ${targets.length} amigos</p><div>${targets.map(id=>{const i=items.find(i=>i.uid===id),t=catalog.find(t=>t.id===i.id);return `<div class="target ${i.found?'done':''}">${i.found?'✓':'○'} ${esc(t.name)}</div>`}).join('')}</div>`;}
function showCatalog(){app.innerHTML=`<section class="content"><div class="toolbar"><button class="back" id="back">← Início</button><span class="mini-label">TOY STORY · FILMES 1 A 5</span></div><h1>Uma turma cheia de histórias</h1><p>O catálogo dos nossos amigos, com nomes em português do Brasil.</p><div class="catalog-controls"><input id="query" aria-label="Buscar brinquedo" placeholder="Qual amigo você procura?"><select id="film" aria-label="Filtrar por filme"><option value="">Todos os filmes</option>${[1,2,3,4,5].map(n=>`<option value="${n}">Toy Story ${n}</option>`).join('')}</select></div><p id="results" class="note" aria-live="polite"></p><div id="cards" class="catalog-grid"></div><p class="note">Catálogo de pesquisa: ${catalog.length} registros, incluindo grupos e variantes. Não é uma lista comprovadamente exaustiva de todos os figurantes. <a href="sources.json" target="_blank" rel="noopener">Fontes e escopo</a>. Os cenários são interpretações artísticas; o quarto de Buzz é temático.</p></section>`;$('#back').onclick=home;function filter(){const q=$('#query').value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),f=Number($('#film').value);const list=catalog.filter(t=>t.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q)&&(!f||t.films.includes(f)));$('#results').textContent=`${list.length} registros encontrados`;$('#cards').innerHTML=list.map(t=>`<article class="catalog-card"><div class="catalog-avatar">${t.asset?`<img src="${esc(t.asset)}" alt="${esc(t.name)} em pose estática">`:esc(t.name.split(' ').slice(0,2).map(w=>w[0]).join(''))}</div><small>${esc(t.group)} · ${t.kind==='collective'?'Grupo':t.kind==='variant'?'Variante':'Brinquedo'}</small><h3>${esc(t.name)}</h3><p>${esc(t.description)}</p><p>Toy Story ${t.films.join(' · ')}</p><small>${t.asset?'Imagem disponível':'Imagem pendente'} · Pose estática</small><p><a href="${esc(t.sourceUrl)}" target="_blank" rel="noopener">Consultar fonte ↗</a></p></article>`).join('')||'<p class="empty">Nenhum amigo com esse nome. Tente outro!</p>'}$('#query').oninput=filter;$('#film').onchange=filter;filter();window.scrollTo(0,0)}
home();
